edits.newText:
// B-015: show the jump glyph when the playing track lives outside
// the browsed folder. Additionally, when the playing row exists
// inside the current folder but is scrolled out of view, expose
// the same action so users can quickly bring it into view.
final hasPlaying =
    playingPath != null && playingPath.isNotEmpty;
final divergent =
    hasPlaying && p.dirname(playingPath!) != (path ?? '');
final visible = hasPlaying
    ? browserController.isTrackVisible(playingPath!)
    : false;
final shouldOfferAction = divergent || !visible;
final showJumpGlyph = resolveJumpGlyphVisible(shouldOfferAction);

